        */
        return Parsable.parse[Int64](hex_num, 16)
    }
}

import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    /*
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    */

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        /*
        Initialize NumberWordFormatter object.
        */
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match x {
            case Some(value) => this.format_string(value)
            case None => ""
        }
    }

    public func format_string(x: String): String {
        let parts = x.split('.')
        let integer_part = parts[0]
        let decimal_part = if parts.length > 1 { parts[1] } else { "" }

        let integer_words = this.convert_integer_part(integer_part)

        let decimal_words = if decimal_part != "" {
            " AND " + this.convert_decimal_part(decimal_part) + " ONLY"
        } else {
            " ONLY"
        }

        integer_words + decimal_words
    }

    private func convert_integer_part(s: String): String {
        if s == "0" {
            return "ZERO"
        }

        let cleaned = s.trim_start_matches('0')
        let length = cleaned.length
        let groups = (length + 2) / 3
        let padded_length = groups * 3
        let padded = "0".repeat(padded_length - length) + cleaned

        var result: Array<String> = []

        for i in 0..<groups {
            let start = i * 3
            let end = start + 3
            let chunk = padded.substring(start, end)
            if chunk != "000" {
                let chunk_words = this.trans_three(chunk)
                let suffix = this.parse_more(groups - i - 1)
                if suffix != "" {
                    result.push(chunk_words + " " + suffix)
                } else {
                    result.push(chunk_words)
                }
            }
        }

        result.join(" ")
    }

    private func convert_decimal_part(s: String): String {
        var words: Array<String> = []
        for ch in s.to_unicode_chars() {
            let digit = ch.to_string().parse_int().get_or_default(0)
            words.push(this.NUMBER[digit])
        }
        words.join(" ")
    }

    public func trans_two(s: String): String {
        let num = s.parse_int().get_or_default(0)
        if num < 10 {
            return this.NUMBER[num]
        } else if num < 20 {
            return this.NUMBER_TEEN[num - 10]
        } else {
            let tens = num / 10
            let ones = num % 10
            if ones == 0 {
                return this.NUMBER_TEN[tens - 1]
            } else {
                return this.NUMBER_TEN[tens - 1] + " " + this.NUMBER[ones]
            }
        }
    }

    public func trans_three(s: String): String {
        let num = s.parse_int().get_or_default(0)
        if num == 0 {
            return ""
        }

        let hundreds = num / 100
        let remainder = num % 100

        if hundreds == 0 {
            return this.trans_two(remainder.to_string().pad_start(2, '0'))
        }

        let hundred_word = this.NUMBER[hundreds] + " HUNDRED"
        if remainder == 0 {
            return hundred_word
        } else {
            return hundred_word + " AND " + this.trans_two(remainder.to_string().pad_start(2, '0'))
        }
    }

    public func parse_more(i: Int64): String {
        if i < this.NUMBER_MORE.length {
            return this.NUMBER_MORE[i]
        } else {
            return ""
        }
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    /*
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    */

    public init() {}

    public func replace(string: String): String {
        /*
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: String, the input string containing numeric character references.
        :return: String, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        */
        var result = ArrayList<Rune>()
        var i = 0
        while i < string.size() {
            if string[i] == '&' && i + 1 < string.size() && string[i + 1] == '#' {
                var j = i + 2
                var is_hex = false
                if j < string.size() && (string[j] == 'x' || string[j] == 'X') {
                    is_hex = true
                    j += 1
                }

                var start = j
                while j < string.size() && string[j] != ';' {
                    j += 1
                }

                if j < string.size() && string[j] == ';' && j > start {
                    var num_str = string.substring(start, j - start)
                    var code_point: Int
                    if is_hex {
                        code_point = Int.parse_radix(num_str, 16).get_or_else(0)
                    } else {
                        code_point = Int.parse_radix(num_str, 10).get_or_else(0)
                    }

                    if code_point > 0 {
                        result.add_all(String.from_code_point(code_point).to_runes())
                        i = j + 1
                        continue
                    }
                }
            }
            result.add(string[i])
            i += 1
        }
        return String.from_runes(result)
    }

    public static func is_hex_char(char: Rune): Bool {
        /*
        Determines whether a given character is a hexadecimal digit.
        :param char: Rune, the character to check.
        :return: Bool, true if the character is a hexadecimal digit, false otherwise.
        >>> NumericEntityUnescaper.is_hex_char(r'a')
        true

        */
        var c = char.to_char()
        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
    }
}

import std.collection.ArrayList
import std.collection.HashMap
