import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    /*
    The class provides vector operations, including calculating similarity, cosine similarities, average similarity, and IDF weights.
    */

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        var dot_product: Float64 = 0.0
        var norm1: Float64 = 0.0
        var norm2: Float64 = 0.0

        for i in 0..<vector_1.size() {
            let v1 = vector_1.get(i)
            let v2 = vector_2.get(i)
            dot_product += v1 * v2
            norm1 += v1 * v1
            norm2 += v2 * v2
        }

        if norm1 == 0.0 || norm2 == 0.0 {
            return 0.0
        }

        return dot_product / (sqrt(norm1) * sqrt(norm2))
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for i in 0..<vectors_all.size() {
            let vec = vectors_all.get(i)
            let sim = VectorUtil.similarity(vector_1, vec)
            result.add(sim)
        }
        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if vector_list_1.size() == 0 || vector_list_2.size() == 0 {
            return 0.0
        }

        var sum1 = ArrayList<Float64>()
        for i in 0..<vector_list_1.get(0).size() {
            sum1.add(0.0)
        }
        for vec in vector_list_1 {
            for i in 0..<vec.size() {
                sum1.set(i, sum1.get(i) + vec.get(i))
            }
        }
        for i in 0..<sum1.size() {
            sum1.set(i, sum1.get(i) / Float64(vector_list_1.size()))
        }

        var sum2 = ArrayList<Float64>()
        for i in 0..<vector_list_2.get(0).size() {
            sum2.add(0.0)
        }
        for vec in vector_list_2 {
            for i in 0..<vec.size() {
                sum2.set(i, sum2.get(i) + vec.get(i))
            }
        }
        for i in 0..<sum2.size() {
            sum2.set(i, sum2.get(i) / Float64(vector_list_2.size()))
        }

        return VectorUtil.similarity(sum1, sum2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        for entry in number_dict.entrySet() {
            let key = entry.key
            let count = entry.value
            let weight = log((Float64(total_num) + 1.0) / (count + 1.0))
            result.put(key, weight)
        }
        return result
    }
}

